    int N, K, U;
    scanf("%d %d %d", &N, &K, &U);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < K; j++) {
            scanf("%d", &card[i][j]);
        }
    }

    for (int p = 1; p <= U; p++) {
        int x;
        scanf("%d", &x);
        pos[x] = p;
    }

    int best = U + 1;
    int wc = 0;

    for (int i = 0; i < N; i++) {
        int time = 0;
        for (int j = 0; j < K; j++) {
            int p = pos[card[i][j]];
            if (p > time) time = p;
        }

        if (time < best) {
            best = time;
            wc = 0;
            winners[wc++] = i + 1;
